        for target in group:
            if target == donor:
                continue
            for dy in range(height):
                sr = donor[0] + dy
                tr = target[0] + dy
                se, te = row_end(grid[sr]), row_end(grid[tr])
                for x in range(te + 1, se + 1):
                    if grid[sr][x] != bg:
                        out[tr][x] = 1

